import{_ as d,o as r,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"片型图谱：这支片子该长什么样","description":"","frontmatter":{},"headers":[],"relativePath":"method/ad-formats.md","filePath":"method/ad-formats.md","lastUpdated":1787456457000}'),o={name:"method/ad-formats.md"};function e(n,t,h,i,l,p){return r(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="片型图谱-这支片子该长什么样" tabindex="-1">片型图谱：这支片子该长什么样 <a class="header-anchor" href="#片型图谱-这支片子该长什么样" aria-label="Permalink to &quot;片型图谱：这支片子该长什么样&quot;">​</a></h1><p>Big Idea 决定<strong>说什么</strong>，片型决定<strong>用什么容器装</strong>。容器错了，再好的内容也会漏出来。</p><p>这一篇是通用的片型查表。想看它在一个具体产品上怎么用，读 <a href="/cases/case-04-fries-crisp-formats">案例 04 附 · 片型可行性分析</a>——那篇是本篇方法的一次完整落地。</p><h2 id="它在链路里的位置" tabindex="-1">它在链路里的位置 <a class="header-anchor" href="#它在链路里的位置" aria-label="Permalink to &quot;它在链路里的位置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>拆 brief  →  片型可行性  →  找洞察  →  定 Big Idea  →  分镜  →  生成</span></span>
<span class="line"><span>             ↑</span></span>
<span class="line"><span>        这一步经常被跳过</span></span></code></pre></div><p>跳过的后果是：想了一个很漂亮的创意，做到分镜阶段才发现这个形态根本承载不了它，或者合规上根本不能做。</p><div class="tip custom-block"><p class="custom-block-title">一句话</p><p><strong>片型不是选出来的，是被产品条件排除到只剩一两个的。</strong></p></div><hr><h2 id="_1-十一种片型速查" tabindex="-1">① 十一种片型速查 <a class="header-anchor" href="#_1-十一种片型速查" aria-label="Permalink to &quot;① 十一种片型速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>片型</th><th>核心是什么</th><th>典型时长</th><th>AI 适配</th></tr></thead><tbody><tr><td><strong>产品演示片</strong></td><td>卖点直给，功能可视化</td><td>15–30s</td><td>★★★★☆</td></tr><tr><td><strong>感官 / ASMR 片</strong></td><td>放大质感与声音，不讲道理</td><td>6–15s</td><td>★★★★★</td></tr><tr><td><strong>工艺解构片</strong></td><td>把看不见的过程视觉化</td><td>15–45s</td><td>★★★★★</td></tr><tr><td><strong>视觉奇观 / 概念片</strong></td><td>超现实、变形、不可能的物理</td><td>15–30s</td><td>★★★★★</td></tr><tr><td><strong>情景短剧</strong></td><td>用小故事包装使用场景</td><td>15–60s</td><td>★★★☆☆</td></tr><tr><td><strong>悬念反转片</strong></td><td>前 3 秒制造疑问，结尾揭晓</td><td>15–30s</td><td>★★★☆☆</td></tr><tr><td><strong>UGC / 素人分享</strong></td><td>刻意不精致，换真实感</td><td>15–30s</td><td>★★★☆☆</td></tr><tr><td><strong>信息型（动态海报 / 清单）</strong></td><td>不叙事，只做信息密度</td><td>静态–10s</td><td>★★★★☆</td></tr><tr><td><strong>品牌情感故事片</strong></td><td>讲价值观，不讲产品</td><td>60s–3min</td><td>★★☆☆☆</td></tr><tr><td><strong>代言人口播 / 达人测评</strong></td><td>靠人的可信度背书</td><td>15–60s</td><td>★☆☆☆☆</td></tr><tr><td><strong>对比片</strong></td><td>前后对比、同类对比</td><td>15–30s</td><td>✕ 合规</td></tr></tbody></table><p>星级是<strong>用 AI 做这一类的相对优势</strong>，不是这一类本身的好坏。对比片的 ✕ 与技术无关，见 ④。</p><hr><h2 id="_2-逐类展开" tabindex="-1">② 逐类展开 <a class="header-anchor" href="#_2-逐类展开" aria-label="Permalink to &quot;② 逐类展开&quot;">​</a></h2><h3 id="a-组-·-产品本体类" tabindex="-1">A 组 · 产品本体类 <a class="header-anchor" href="#a-组-·-产品本体类" aria-label="Permalink to &quot;A 组 · 产品本体类&quot;">​</a></h3><p>镜头里只有产品，没有人。<strong>AI 在这一组的优势最大</strong>——不用处理人脸、口型、表演。</p><table tabindex="0"><thead><tr><th>片型</th><th>适合什么产品</th><th>决定成败的一步</th><th>常见翻车</th></tr></thead><tbody><tr><td><strong>产品演示</strong></td><td>功能有可视差异的（清洁、收纳、工具）</td><td>找到那个「一看就懂」的动作</td><td>把说明书拍成视频，信息全但没人看</td></tr><tr><td><strong>感官 / ASMR</strong></td><td>食品、饮料、美妆、纺织</td><td>声音设计，不是画面</td><td>只做画面不做声音，质感立刻掉一半</td></tr><tr><td><strong>工艺解构</strong></td><td>差异化在制程里的（食品工艺、材料、芯片）</td><td>找到实拍不到的那个核心画面</td><td>从展示做法滑向宣称好处，踩合规红线</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">感官片的一个硬规矩</p><p>音效不是「配」的，是「拍」的。碰撞声、断裂声、咀嚼声，每一条要单独设计。参考 <a href="/cases/case-03-fries-social">案例 03 · 快餐薯条社媒短视频</a>。</p></div><h3 id="b-组-·-人出镜类" tabindex="-1">B 组 · 人出镜类 <a class="header-anchor" href="#b-组-·-人出镜类" aria-label="Permalink to &quot;B 组 · 人出镜类&quot;">​</a></h3><p>**这一组是 AI 目前最弱的一环。**真人表演、口型同步、微表情——生成模型在这三件事上还没到能交付的水平。</p><table tabindex="0"><thead><tr><th>片型</th><th>靠什么起效</th><th>用 AI 做的风险</th></tr></thead><tbody><tr><td><strong>代言人口播</strong></td><td>权威感、颜值、信任转移</td><td>口型对不上、微表情僵硬，观众第一眼就出戏</td></tr><tr><td><strong>达人测评</strong></td><td>「他跟我一样」的同侪信任</td><td>一旦被看出是 AI，真实感归零，反噬品牌</td></tr><tr><td><strong>UGC / 素人分享</strong></td><td>粗糙感本身就是可信度</td><td>相对可做——因为观众对画质的容忍度高</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">客户坚持要真人怎么办</p><p>**这一类不要用 AI 做。**真人出镜的内容找真人拍，成本反而更低、风险更小。</p><p>硬用 AI 做真人口播，是拿自己的短板去打别人的长板。能力边界要诚实划出来。相关限制见 <a href="/prompts/spokesperson">人物代言</a>、<a href="/prompts/ugc-style">UGC 仿真风</a>。</p></div><h3 id="c-组-·-叙事类" tabindex="-1">C 组 · 叙事类 <a class="header-anchor" href="#c-组-·-叙事类" aria-label="Permalink to &quot;C 组 · 叙事类&quot;">​</a></h3><p>有起承转合，考验的是结构不是画面。</p><table tabindex="0"><thead><tr><th>片型</th><th>结构</th><th>门槛在哪</th></tr></thead><tbody><tr><td><strong>情景短剧</strong></td><td>场景 → 冲突 → 产品介入 → 解决</td><td>人物一致性。同一个角色跨镜头会漂</td></tr><tr><td><strong>悬念反转片</strong></td><td>疑问 → 铺垫 → 揭晓</td><td>前 3 秒。竖屏信息流里，铺垫没人等</td></tr><tr><td><strong>品牌情感故事片</strong></td><td>情绪线，产品只在结尾出现</td><td>体量与阶段。没有品牌资产时做，是在正确的事上抢错时机</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">人物一致性的规避办法</p><p>不要追求「让 AI 生成一个稳定的角色」，要<strong>把镜头拆到不需要稳定</strong>：背影、手部、局部、快切。改结构比调模型省一个数量级的时间。做法见 <a href="/method/storyboard">分镜设计</a>。</p></div><h3 id="d-组-·-其他" tabindex="-1">D 组 · 其他 <a class="header-anchor" href="#d-组-·-其他" aria-label="Permalink to &quot;D 组 · 其他&quot;">​</a></h3><table tabindex="0"><thead><tr><th>片型</th><th>什么时候用</th><th>注意</th></tr></thead><tbody><tr><td><strong>视觉奇观 / 概念片</strong></td><td>产品本身没什么可拍，靠概念取胜</td><td>AI 在这一类的优势是<strong>碾压性</strong>的，因为实拍根本做不出来</td></tr><tr><td><strong>信息型</strong></td><td>电商详情页、促销节点、榜单</td><td>不要硬加叙事。它的任务是信息密度不是打动人</td></tr><tr><td><strong>对比片</strong></td><td>——见下</td><td>直接对比同类产品有明确法律风险</td></tr></tbody></table><hr><h2 id="_3-创意手法-与片型正交" tabindex="-1">③ 创意手法（与片型正交） <a class="header-anchor" href="#_3-创意手法-与片型正交" aria-label="Permalink to &quot;③ 创意手法（与片型正交）&quot;">​</a></h2><p>片型是容器，手法是装进去的东西。<strong>同一个片型可以用任何一种手法</strong>，不要把这两层混在一起讨论。</p><table tabindex="0"><thead><tr><th>手法</th><th>做法</th><th>风险</th></tr></thead><tbody><tr><td><strong>夸张放大</strong></td><td>把一个特性推到荒谬</td><td>过头会显得假，反而削弱可信度</td></tr><tr><td><strong>类比 / 隐喻</strong></td><td>用熟悉的解释陌生的</td><td>类比选错，观众记住喻体忘了产品</td></tr><tr><td><strong>反差与反转</strong></td><td>先建立预期再打破</td><td>反转太弱等于没有</td></tr><tr><td><strong>拟人化</strong></td><td>让产品或抽象概念开口</td><td>容易滑向幼稚</td></tr><tr><td><strong>问题—解决</strong></td><td>最古老也最稳的结构</td><td>也最像广告，观众防备心最高</td></tr><tr><td><strong>幽默 / 自嘲</strong></td><td>降低防备心</td><td>品牌调性要撑得住，严肃品类别碰</td></tr><tr><td><strong>重复洗脑</strong></td><td>牺牲好感度换记忆度</td><td>效果真实存在，但会消耗品牌资产</td></tr><tr><td><strong>悬念</strong></td><td>把答案往后放</td><td>赌观众看完，竖屏里赢面小</td></tr><tr><td><strong>情绪共鸣</strong></td><td>不说产品，说人的处境</td><td>共鸣不准就是自我感动</td></tr><tr><td><strong>借势 / 热梗</strong></td><td>蹭现成的注意力</td><td>保质期以周计，用完即弃</td></tr></tbody></table><p>选手法的时候回头看一眼 <a href="/method/big-idea">Big Idea 的判断清单</a>——手法是为洞察服务的，不是拿来凑数的。</p><hr><h2 id="_4-ai-让性价比排序重新洗牌" tabindex="-1">④ AI 让性价比排序重新洗牌 <a class="header-anchor" href="#_4-ai-让性价比排序重新洗牌" aria-label="Permalink to &quot;④ AI 让性价比排序重新洗牌&quot;">​</a></h2><p>这是本篇最需要更新旧经验的一节。</p><table tabindex="0"><thead><tr><th>片型</th><th>五年前</th><th>现在</th><th>为什么变</th></tr></thead><tbody><tr><td><strong>工艺解构片</strong></td><td>最贵之一</td><td>最便宜之一</td><td>过去要进车间实拍或做三维动画；现在生成就行</td></tr><tr><td><strong>视觉奇观片</strong></td><td>最贵</td><td>便宜</td><td>特效成本坍塌</td></tr><tr><td><strong>品牌情感故事片</strong></td><td>贵</td><td>仍然贵</td><td>贵在剧本和表演，AI 省不掉</td></tr><tr><td><strong>代言人口播</strong></td><td>便宜</td><td>仍然便宜（找真人）</td><td>AI 做反而更贵——返工次数不可控</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">不要沿用旧的片型性价比直觉</p><p>「工艺片太贵，我们做不起」这句话在今天已经不成立。成本结构变了，<strong>哪个片型划算这件事必须重新评估一遍</strong>，不能凭经验排序。</p></div><h3 id="合规是筛子-不是最后一道检查" tabindex="-1">合规是筛子，不是最后一道检查 <a class="header-anchor" href="#合规是筛子-不是最后一道检查" aria-label="Permalink to &quot;合规是筛子，不是最后一道检查&quot;">​</a></h3><p>对比片被否掉，与创意质量和技术能力都无关。直接对比同类产品容易构成<strong>贬低同类</strong>，在广告法下有明确风险。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通项目：  想创意 → 选片型 → 做出来 → 法务检查 → 小改</span></span>
<span class="line"><span>高敏品类：  合规边界 → 排除片型 → 在剩下的里想创意 → 法务复核</span></span></code></pre></div><p>食品功效、医疗、金融、化妆品功效——这些品类必须走第二条路。放在最后检查，被砍掉的不是文案，是整支片子。</p><div class="tip custom-block"><p class="custom-block-title">对比片的替代方案</p><p>只展示自己，不出现任何参照物。<strong>观众自己脑补的对比，比你摆在屏幕上的更有说服力。</strong></p></div><hr><h2 id="_5-怎么选-排除法四步" tabindex="-1">⑤ 怎么选：排除法四步 <a class="header-anchor" href="#_5-怎么选-排除法四步" aria-label="Permalink to &quot;⑤ 怎么选：排除法四步&quot;">​</a></h2><p>不要头脑风暴各种可能性，要做减法。</p><p>**第一步：列产品硬条件。**每一条都会否掉某些片型。</p><table tabindex="0"><thead><tr><th>维度</th><th>要问的问题</th></tr></thead><tbody><tr><td>差异化在哪</td><td>感官？工艺？功能？价格？——决定内容有没有得讲</td></tr><tr><td>核心画面能不能实拍</td><td>实拍不到的，正是 AI 的机会</td></tr><tr><td>客单价与体量</td><td>决定制作预算的天花板</td></tr><tr><td>合规敏感度</td><td>高敏品类先划红线</td></tr><tr><td>品牌阶段</td><td>新品讲「为什么值得买」，成熟品牌才讲价值观</td></tr></tbody></table><p>**第二步：用合规砍一遍。**先砍，别等做完。</p><p><strong>第三步：在剩下的里按投放场景挑。</strong></p><table tabindex="0"><thead><tr><th>投放场景</th><th>要什么</th><th>优先片型</th></tr></thead><tbody><tr><td>电商详情页</td><td>说服</td><td>工艺解构、产品演示、信息型</td></tr><tr><td>短视频信息流</td><td>3 秒抓人</td><td>感官 ASMR、悬念反转、UGC</td></tr><tr><td>品牌官宣 / 发布会</td><td>调性</td><td>视觉奇观、品牌情感故事</td></tr><tr><td>私域 / 社群</td><td>可信</td><td>UGC、达人测评</td></tr></tbody></table><p><strong>第四步：剩下不止一个？做组合拳。</strong></p><div class="tip custom-block"><p class="custom-block-title">组合拳共用素材</p><p>一支工艺解构片 + 一支感官短片，可以共用同一批生成素材，只是剪辑取向不同。<strong>成本增量远小于两支片子。</strong></p><p>典型分工：感官片负责在信息流里拦人，工艺片负责在详情页里说服。案例 04 走的就是这个组合。</p></div><hr><h2 id="三个常见误区" tabindex="-1">三个常见误区 <a class="header-anchor" href="#三个常见误区" aria-label="Permalink to &quot;三个常见误区&quot;">​</a></h2><p><strong>误区一：按「哪个片型看起来高级」排序。</strong> 片型没有高低，只有匹不匹配。品牌情感故事片放在一个新品上，是浪费。</p><p><strong>误区二：先想创意再挑片型。</strong> 顺序反了。创意得在容器里长，容器定了创意才有边界——<strong>没有边界的创意想不完，也落不了地。</strong></p><p><strong>误区三：把 AI 的短板硬扛过去。</strong> 人出镜类扛不过去。与其花三天调口型，不如换片型或者找真人。</p><hr><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>片型定了，往下走 → <a href="/method/big-idea">Big Idea 与洞察</a></li><li>创意定了，排分镜 → <a href="/method/storyboard">分镜设计：镜头语言翻译表</a></li><li>完整链路 → <a href="/method/workflow-sop">从 brief 到成片：完整链路 SOP</a></li><li>本篇方法的一次完整落地 → <a href="/cases/case-04-fries-crisp-formats">案例 04 附 · 片型可行性分析</a></li></ul>`,60)])])}const b=d(o,[["render",e]]);export{c as __pageData,b as default};
